      await env.writeFile('apps/demo/widget.js', "import './components/a.js';");
      await env.writeFile('apps/demo/components/a.js', 'jsr.render({});');

      final rev1 = await JsAppEngine.computeSourceRevision(
        env,
        'apps/demo',
        'widget.js',
