      final env = MemoryExecutionEnv();
      await env.writeFile('apps/demo/manifest.json', '{"id":"demo"}');
      await env.writeFile('apps/demo/widget.js', 'jsr.render({});');
      final rev1 = await JsAppEngine.computeSourceRevision(
        env,
