    test('computeSourceRevision hashes the WHOLE source tree — a '
        'helper-file edit re-arms the error gate (review thread 6)', () async {
      final env = MemoryExecutionEnv();
      await env.writeFile(
        'apps/demo/manifest.json',
        '{"id":"demo","name":"Demo"}',
