      );
      final rev2 = await JsAppEngine.computeSourceRevision(
        env,
        'apps/demo',
        'widget.js',
      );
      expect(rev2, isNot(rev1));

      await env.writeFile(
        'apps/demo/widget.js',
        "import './components/a.js'; // v3",
      );
      final rev3 = await JsAppEngine.computeSourceRevision(
        env,
        'apps/demo',
        'widget.js',
